  'health.quarantine.analysis.loader-entry-collision': '插件注册了已由当前客户端内置功能占用的 Loader 条目。客户端保留内置实现并隔离该插件，避免重复条目阻断整个界面启动。',
  'health.quarantine.analysis.loader-lifecycle-failed': '插件模块能够加载，但在启动或注册服务时抛出错误。客户端已根据 Loader 条目和 Bundle 来源确认责任插件并将其隔离，让其余插件和设置能够继续启动。',
