  'health.quarantine.solution.incompatible-host-dependency': '优先查找适配当前 DSH 的插件更新；确认插件或客户端已升级后再恢复。若长期没有兼容版本，请彻底卸载该插件。',
  'health.quarantine.solution.convergence-failed': '使用“重新链接并恢复”让 pnpm 重新收敛到客户端内置依赖。失败时会自动回滚，插件仍保持隔离。',
  'health.quarantine.solution.orphaned-bundle': '若仍需使用该插件，可从原来源重新安装；不再需要时应彻底卸载，以清理失效的 Loader 引用。',
