  'health.quarantine.solution.client-module-unavailable': '当前插件版本与此客户端代际不兼容，重复恢复原版本仍会失败。请移除旧隔离版本并到插件市场安装兼容更新；若市场仍返回旧版，请等待新版本通过供应链安全等待期后再安装。',
  'health.quarantine.solution.loader-module-unresolvable': '当前插件包内的加载模块名或发布内容不完整，重复恢复同一版本仍会失败。请移除旧隔离版本并到插件市场查找修正后的版本；若暂无更新，请联系插件作者修正 Bundle Patch。',
  'health.quarantine.solution.loader-dependency-unavailable': '请安装与当前 DSH 版本兼容的插件更新。若涉及 @deepseek-ai/dsh-* Host 包或已移除的导出 API，不要手动安装另一版 Host 包；这表示插件面向另一代 DSH 构建，应由插件作者迁移 API 并发布兼容版本。',
