  'lab.scenario.hostCompatible.title': 'Compatible Host shadow copy',
  'lab.scenario.hostCompatible.body': 'Verify that a second Cordis identity can converge to the bundled runtime safely.',
  'lab.scenario.hostIncompatible.title': 'Incompatible Host dependency',
  'lab.scenario.hostIncompatible.body': 'Trace an incompatible dsh-tools edge to its root plugin and quarantine it.',
  'lab.scenario.orphan.title': 'Orphaned bundle',
  'lab.scenario.orphan.body': 'Find a ghost Loader entry whose plugin package has disappeared.',
  'lab.scenario.quarantineRemoval.title': 'Quarantine removal residue',
  'lab.scenario.quarantineRemoval.body': 'Write the repair-report, diagnostic-report, and lockfile references left by a legacy uninstall, then verify bounded detection and cleanup.',
  'lab.scenario.clientModule.title': 'dsh-font client compatibility',
  'lab.scenario.clientModule.body': 'Install the packaged dsh-font 1.1.0 fixture, trigger its real missing client module, and verify automatic quarantine followed by a usable main UI.',
  'lab.scenario.loaderPackageNameMismatch.title': 'Scoped plugin Loader name mismatch',
  'lab.scenario.loaderPackageNameMismatch.body': 'Install a safe offline scoped fixture whose Bundle Patch deliberately loads a missing unscoped module, then verify immediate attribution and quarantine after installation.',
  'lab.scenario.startupTimeout.title': 'Startup operation timeout and rollback',
  'lab.scenario.startupTimeout.body': 'Simulate a timed-out startup command and verify process cancellation, rollback evidence, and continued startup. This scenario is unchecked by default.',
  'lab.scenario.transactionInterrupted.title': 'Interrupted plugin activation recovery',
  'lab.scenario.transactionInterrupted.body': 'Activate an inert candidate in an isolated home, then use a fresh CLI and its journal to restore the previous dependency directory. Unchecked by default; the active Profile is unchanged.',
  'lab.scenario.loaderDependency.title': 'Missing aggregate plugin dependency',
  'lab.scenario.loaderDependency.body': 'Install an offline aggregate plugin whose Loader entry resolves but whose published code deliberately requests a missing internal Host dependency, then verify immediate root attribution and quarantine.',
  'lab.scenario.loaderExport.title': 'Plugin expects an unavailable DSH API',
  'lab.scenario.loaderExport.body': 'Install an offline plugin that reproduces the real failure: its dependency exists, but the plugin expects an API that this DSH generation does not export. Resume the real Harness and verify attribution and quarantine before diagnostic mode.',
  'lab.scenario.legacySessionApi.title': 'Plugin uses a legacy Session API',
  'lab.scenario.legacySessionApi.body': 'Install an inert offline plugin carrying the reproduced session.events pattern. Verify accurate attribution without automatically quarantining on static evidence. This scenario is unchecked by default.',
  'lab.scenario.immutableAgentInput.title': 'Plugin mutates frozen conversation input',
  'lab.scenario.immutableAgentInput.body': 'Install an offline failing plugin that mutates a frozen agent/pre-step text block and breaks every conversation. Verify attribution and disable or uninstall guidance without automatically quarantining on static evidence. This scenario is unchecked by default.',
  'lab.scenario.settingsInvalid.title': 'Invalid settings.yaml',
  'lab.scenario.settingsInvalid.body': 'Write duplicate settings keys and verify that the normal Profile reports the configuration error, diagnostic mode uses an isolated empty document, and the original file remains unchanged.',
  'lab.scenario.module.title': 'Missing module directory',
  'lab.scenario.module.body': 'Verify module-resolution failure attribution to the owning plugin.',
  'lab.scenario.patch.title': 'Invalid Profile patch',
  'lab.scenario.patch.body': 'Locate malformed cordis.patch.yml syntax in a test copy.',
  'lab.scenario.duplicate.title': 'Duplicate Loader entry',
  'lab.scenario.duplicate.body': 'Reproduce an external plugin registering the same Loader entry as a built-in client feature, then verify pre-start attribution, quarantine, and safe cleanup.',
  'lab.scenario.lifecycle.title': 'Loader lifecycle failure',
  'lab.scenario.lifecycle.body': 'Verify mount failure, rollback, and root-plugin attribution.',
  'lab.scenario.build.title': 'Blocked build script',
  'lab.scenario.build.body': 'Use a bundled harmless script to verify exact allowBuilds approval.',
  'lab.scenario.interrupted.title': 'Interrupted repair recovery',
  'lab.scenario.interrupted.body': 'Verify that a later run reads the recovery journal and cleans the scene.',
