  'health.quarantine.conflict.requires': 'Plugin declares',
  'health.quarantine.conflict.hostUses': 'Bundled Host',
  'health.quarantine.conflict.incompatible': 'the ranges are incompatible, so the plugin cannot safely share the runtime and was removed from the active Profile',
  'health.quarantine.conflict.convergence': 'the ranges are compatible, but dependency convergence failed, so the plugin was removed from the active Profile',
  'health.quarantine.analysis.incompatible-host-version': 'The plugin\'s own compatibility manifest explicitly excludes this Harness version. The client blocked activation before executing plugin code so one known-incompatible release cannot take down other plugins.',
  'health.quarantine.analysis.incompatible-host-dependency': 'The plugin carries an identity-sensitive Host dependency that is incompatible with the bundled version, so both copies cannot safely coexist in one process.',
  'health.quarantine.analysis.convergence-failed': 'The dependency ranges appear compatible, but the package manager could not converge the plugin onto the bundled Host instance.',
  'health.quarantine.analysis.orphaned-bundle': 'The plugin remains in the Loader list even though the Profile dependency manifest can no longer manage or uninstall it.',
  'health.quarantine.analysis.build-script-blocked': 'pnpm blocked a dependency build script. The client deactivated the plugin so the main interface can still start; approve and retry only after verifying the source.',
  'health.quarantine.analysis.client-module-unavailable': 'The plugin client requested a module that this build cannot provide. The client deactivated the plugin so the rest of the application can start; retry after updating the plugin or client.',
  'health.quarantine.analysis.loader-module-unresolvable': 'The plugin root package is installed, but its Bundle Patch references a Loader module that cannot resolve. The client immediately deactivated the plugin so this broken version cannot block the next startup.',
  'health.quarantine.analysis.loader-dependency-unavailable': 'The Loader module resolves, but its published code imports an internal dependency that the active Profile cannot provide or expects an export API absent from this DSH generation. The client attributes the failure to the outer plugin and quarantines it so an incompatible plugin cannot take down the whole interface.',
  'health.quarantine.analysis.loader-entry-collision': 'The plugin registers a Loader entry already owned by a feature built into this client. The client keeps the built-in implementation and quarantines the plugin so a duplicate entry cannot block the entire interface from starting.',
  'health.quarantine.analysis.loader-lifecycle-failed': 'The plugin module loaded, but it threw while starting or registering services. The client proved the responsible plugin from the Loader entry and Bundle source, then quarantined it so the remaining plugins and settings can continue to start.',
  'health.quarantine.solution.title': 'Recommended resolution',
  'health.quarantine.solution.incompatible-host-version': 'Remove the quarantined release and find an update that supports this Harness version in the market. Do not keep restoring the same release; it will remain inactive until its compatibility manifest includes this Host.',
  'health.quarantine.solution.incompatible-host-dependency': 'Look for a plugin release compatible with this DSH version first, then restore it after the plugin or desktop client is updated. Permanently remove it when no compatible release is available.',
  'health.quarantine.solution.convergence-failed': 'Use “Relink and restore” so pnpm can converge the plugin onto the bundled Host dependency. A failed attempt rolls back and leaves the plugin quarantined.',
  'health.quarantine.solution.orphaned-bundle': 'Reinstall the plugin from its original source if you still need it, or remove it permanently to clean the stale Loader entry.',
  'health.quarantine.solution.build-script-blocked': 'Verify the plugin source and requested build package, then approve only the exact displayed build key. Keep it quarantined or remove it if the source is not trusted.',
  'health.quarantine.solution.client-module-unavailable': 'This plugin version targets an incompatible client generation, so restoring the same version will fail again. Remove the old quarantined version and install a compatible update from the market. If the market still resolves the old version, wait for the new release to pass the supply-chain minimum age.',
  'health.quarantine.solution.loader-module-unresolvable': 'The plugin package contains an incorrect Loader module name or incomplete published files, so restoring the same version will fail again. Remove the old quarantined version and find a corrected release in the market; contact the plugin author to fix the Bundle Patch when no update exists.',
  'health.quarantine.solution.loader-dependency-unavailable': 'Install a plugin release compatible with this DSH version. If the failure names an @deepseek-ai/dsh-* Host package or a removed export API, do not install another Host version into the Profile: the plugin targets another DSH generation and its author must migrate the API and publish a compatible build.',
  'health.quarantine.solution.loader-entry-collision': 'This plugin now conflicts with a built-in client feature, so restoring the same version will block startup again. Remove the old release permanently and reinstall only after the plugin publishes a compatible version that no longer registers the duplicate entry.',
  'health.quarantine.solution.loader-lifecycle-failed': 'Check the plugin market for a compatible update first. Restoring the same version may repeat the startup failure; when no update exists, fully uninstall the quarantined version and share the diagnostic report with the plugin author.',
  'health.quarantine.action.compatibleRetry': 'Find compatible version and retry',
