  'health.quarantine.conflict.incompatible': '範囲が互換性がないため、プラグインはランタイムを安全に共有できず、アクティブプロファイルから削除されました',
  'health.quarantine.conflict.convergence': '範囲は互換性がありますが、依存関係の収束に失敗したため、プラグインはアクティブプロファイルから削除されました',
  'health.quarantine.analysis.incompatible-host-version': 'プラグイン自身の互換性マニフェストが明示的にこのハーネスバージョンを除外しています。クライアントはプラグインコードを実行する前に起動をブロックしたため、既知の互換性のないリリースが他のプラグインを停止させることはありません。',
  'health.quarantine.analysis.incompatible-host-dependency': 'プラグインはアイデンティティに依存するホスト依存関係を持っており、バンドルされたバージョンと互換性がないため、両方のコピーを同一プロセスに安全に共存させることはできません。',
  'health.quarantine.analysis.convergence-failed': '依存関係の範囲は互換性があるように見えますが、パッケージマネージャはプラグインをバンドルされたホストインスタンスに収束させることができませんでした。',
  'health.quarantine.analysis.orphaned-bundle': 'プロファイル依存マニフェストがもはや管理またはアンインストールできなくても、プラグインはローダーリストに残っています。',
  'health.quarantine.analysis.build-script-blocked': 'pnpm が依存関係のビルドスクリプトをブロックしました。クライアントはメインインターフェースがまだ起動できるようにプラグインを無効化しました。ソースを確認してから承認し、再試行してください。',
  'health.quarantine.analysis.client-module-unavailable': 'プラグインクライアントは、このビルドでは提供できないモジュールを要求しました。クライアントはアプリケーションの残りを起動できるようにプラグインを無効化しました。プラグインまたはクライアントを更新した後に再試行してください。',
  'health.quarantine.analysis.loader-module-unresolvable': 'プラグインのルートパッケージはインストールされていますが、そのバンドルパッチが解決できないローダーモジュールを参照しています。クライアントはこの壊れたバージョンが次の起動を妨げないよう、直ちにプラグインを無効化しました。',
  'health.quarantine.analysis.loader-dependency-unavailable': 'ローダーモジュールは解決されますが、公開されたコードがアクティブプロファイルが提供できない内部依存関係をインポートするか、このDSH世代に存在しないエクスポート API を期待しています。クライアントはこの失敗を外部プラグインの責任と見なし、互換性のないプラグインがインターフェース全体を停止させないよう隔離しました。',
  'health.quarantine.analysis.loader-lifecycle-failed': 'プラグインモジュールは読み込まれましたが、サービスの開始や登録時にスローしました。クライアントはLoaderエントリとBundleソースから責任プラグインを証明し、残りのプラグインや設定が起動を続けられるように隔離しました。',
  'health.quarantine.analysis.loader-entry-collision': 'プラグインが、このクライアントの組み込み機能ですでに使われている Loader エントリを登録しています。重複したエントリが画面全体の起動を妨げないよう、組み込み実装を維持してプラグインを隔離しました。',
  'health.quarantine.solution.title': '推奨解決',
  'health.quarantine.solution.incompatible-host-version': '隔離されたリリースを削除し、市場でこのハーネスバージョンをサポートするアップデートを探してください。同じリリースを繰り返し復元しないでください。互換性マニフェストにこのホストを含めるまでは非アクティブのままです。',
  'health.quarantine.solution.incompatible-host-dependency': 'まずこのDSHバージョンに対応しているプラグインのリリースを探し、プラグインやデスクトップクライアントが更新された後に復元してください。互換性のあるリリースがなければ、永久に削除してください。',
  'health.quarantine.solution.convergence-failed': '「Relink and restore」を使って、pnpmがプラグインをバンドルされたHost依存に収束できるようにします。失敗した試みはロールバックされ、プラグインは隔離されたままになります。',
  'health.quarantine.solution.orphaned-bundle': 'もしまだ必要なら元のソースからプラグインを再インストールするか、古くなったLoaderエントリをきれいにするために永久に削除してください。',
  'health.quarantine.solution.build-script-blocked': 'プラグインのソースと要求されたビルドパッケージを確認し、表示された正確なビルドキーのみを承認してください。ソースを隔離するか、ソースが信頼できない場合は削除してください。',
  'health.quarantine.solution.client-module-unavailable': 'このプラグインバージョンは互換性のないクライアント世代を対象としているため、同じバージョンの復元は再び失敗します。隔離された古いバージョンを削除し、市場から互換性のあるアップデートをインストールしてください。市場が旧バージョンを解決し続ける場合は、新しいリリースがサプライチェーンの最低年齢を通過するまで待ちましょう。',
  'health.quarantine.solution.loader-module-unresolvable': 'プラグインパッケージには誤ったローダーモジュール名や不完全な公開ファイルが含まれているため、同じバージョンの復元は再び失敗します。古い隔離されたバージョンを削除し、市場で修正されたリリースを探してください。アップデートがない場合はプラグイン作者に連絡してバンドルパッチの修正を依頼してください。',
  'health.quarantine.solution.loader-dependency-unavailable': 'このDSHバージョンに対応したプラグインリリースをインストールしてください。失敗時に@deepseek-ai/dsh-* Hostパッケージの名前が付けられたり、エクスポート・APIが削除された場合、プロファイルに別のHostバージョンをインストールしないでください。プラグインは別のDSH世代を対象としており、その作者はAPIを移行し、互換性のあるビルドを公開する必要があります。',
  'health.quarantine.solution.loader-lifecycle-failed': 'まずプラグイン市場で対応アップデートがないか確認してください。同じバージョンを復元すると起動失敗が繰り返されることがあります。アップデートがない場合は、隔離されたバージョンを完全にアンインストールし、診断レポートをプラグイン作成者と共有してください。',
  'health.quarantine.solution.loader-entry-collision': 'このバージョンは組み込み機能と競合します。旧バージョンを完全に削除し、重複エントリを登録しない互換バージョンが公開されてから再インストールしてください。',
