  'health.quarantine.analysis.incompatible-host-dependency': 'Le plugin comporte une dépendance hôte sensible à l\'identité qui est incompatible avec la version incluse, donc les deux copies ne peuvent pas coexister en toute sécurité dans un même processus.',
