  'health.quarantine.analysis.client-module-unavailable': 'Le client du plugin a demandé un module que cette compilation ne peut pas fournir. Le client a désactivé le plugin afin que le reste de l\'application puisse démarrer ; réessayez après avoir mis à jour le plugin ou le client.',
  'health.quarantine.analysis.loader-module-unresolvable': 'Le paquet racine du plugin est installé, mais son Bundle Patch fait référence à un module Loader qui ne peut pas se résoudre. Le client a désactivé immédiatement le plugin pour que cette version cassée ne bloque pas le prochain démarrage.',
  'health.quarantine.analysis.loader-dependency-unavailable': 'Le module Loader se résout, mais son code publié importe une dépendance interne que le profil actif ne peut pas fournir ou attend un export API absent de cette génération DSH. Le client attribue l\'échec au plugin externe et le met en quarantaine afin qu\'un plugin incompatible ne puisse pas compromettre toute l\'interface.',
  'health.quarantine.analysis.loader-lifecycle-failed': 'Le module plugin s’est chargé, mais il a été lancé lors du lancement ou de l’enregistrement des services. Le client a vérifié le plugin responsable à partir de l’entrée du chargeur et de la source du bundle, puis l’a mis en quarantaine pour que les plugins et paramètres restants puissent continuer à démarrer.',
  'health.quarantine.analysis.loader-entry-collision': 'Le plugin enregistre une entrée Loader déjà utilisée par une fonction intégrée à ce client. Le client conserve l’implémentation intégrée et met le plugin en quarantaine afin que l’entrée dupliquée ne bloque pas tout le démarrage.',
