  'health.quarantine.solution.incompatible-host-dependency': 'Cherchez d’abord une version de plugin compatible avec cette version DSH, puis restaurez-la après la mise à jour du plugin ou du client de bureau. Supprimez-la définitivement lorsqu’aucune version compatible n’est disponible.',
  'health.quarantine.solution.convergence-failed': 'Utilisez « Relier et restaurer » pour que le pnpm puisse converger le plugin vers la dépendance de l’hôte fourni. Une tentative ratée revient en arrière et laisse le plugin en quarantaine.',
  'health.quarantine.solution.orphaned-bundle': 'Réinstaller le plugin depuis sa source d’origine si vous en avez encore besoin, ou le retirer définitivement pour nettoyer l’entrée Loader obsolète.',
  'health.quarantine.solution.build-script-blocked': 'Vérifiez la source du plugin et le package de compilation demandé, puis n’approuvez que la clé de construction affichée exactement. Gardez-la en quarantaine ou supprimez-la si la source n’est pas fiable.',
  'health.quarantine.solution.client-module-unavailable': 'Cette version du plugin cible une génération client incompatible, donc restaurer la même version échouera à nouveau. Retirez l’ancienne version en quarantaine et installez une mise à jour compatible depuis le marché. Si le marché résout toujours l’ancienne version, attendez que la nouvelle version dépasse l’âge minimum de la chaîne d’approvisionnement.',
  'health.quarantine.solution.loader-module-unresolvable': 'Le package de plugins contient un nom de module Loader incorrect ou des fichiers publiés incomplets, donc restaurer la même version échouera à nouveau. Retirez l’ancienne version en quarantaine et trouvez une version corrigée sur le marché ; contactez l’auteur du plugin pour corriger le patch Bundle en cas de mise à jour n’existe.',
  'health.quarantine.solution.loader-dependency-unavailable': 'Installez une version de plugin compatible avec cette version DSH. Si la défaillance nomme un paquet hôte @deepseek-ai/dsh-* ou un API d’exportation supprimé, n’installez pas une autre version de l’hôte dans le profil : le plugin cible une autre génération DSH et son auteur doit migrer le API et publier une version compatible.',
  'health.quarantine.solution.loader-lifecycle-failed': 'Vérifiez d’abord le marché des plugins pour une mise à jour compatible. Restaurer la même version peut répéter l’échec de démarrage ; en l’absence de mise à jour, désinstallez complètement la version en quarantaine et partagez le rapport de diagnostic avec l’auteur du plugin.',
  'health.quarantine.solution.loader-entry-collision': 'Cette version du plugin entre en conflit avec une fonction intégrée. Supprimez complètement l’ancienne version et ne la réinstallez que lorsqu’une version compatible ne déclarant plus l’entrée dupliquée sera disponible.',
