  'lab.confirm.title': 'Das aktuelle Profil üben?',
  'lab.confirm.description': 'Das Harness wird anhalten und echte Diagnostik-Plugins im aktuellen Profil installieren. Reparatur- und Quarantäneergebnisse bleiben bis „Alles wiederherstellen“ erhalten; ändern Sie dieses Profil in der Zwischenzeit nicht von einem anderen DSH-Prozess aus.',
  'lab.confirm.acknowledge': 'ich verstehe, dass diese Übung das aktuelle Profil dauerhaft verändert und bestätigt, dass keine andere DSH- oder Plugin-Installation läuft',
  'lab.confirm.cancel': 'Rückkehr zum Sandkasten',
  'lab.confirm.start': 'Bestätigen und starten',
  'lab.scenario.hostCompatible.title': 'Kompatible Host-Schattenkopie',
  'lab.scenario.hostCompatible.body': 'Überprüfen Sie, dass eine zweite Cordis-Identität sicher auf die gebündelte Laufzeit konvergieren kann.',
  'lab.scenario.hostIncompatible.title': 'Inkompatible Host-Abhängigkeit',
  'lab.scenario.hostIncompatible.body': 'Verfolgen Sie eine inkompatible DSH-Tools-Kante zu ihrem Root-Plugin und isolieren Sie es.',
  'lab.scenario.orphan.title': 'Verwaistes Bündel',
  'lab.scenario.orphan.body': 'Finde einen Ghost Loader-Eintrag, dessen Plugin-Paket verschwunden ist.',
  'lab.scenario.quarantineRemoval.title': 'Rückstände zur Quarantäneentfernung',
  'lab.scenario.quarantineRemoval.body': 'Schreiben Sie die Reparaturbericht-, Diagnosebericht- und Sperrdateienreferenzen, die durch eine Altinstallation zurückgelassen wurden, und überprüfen Sie dann die Detektierung und Bereinigung der begrenzten Authentifizierung.',
  'lab.scenario.clientModule.title': 'dsh-Font-Client-Kompatibilität',
  'lab.scenario.clientModule.body': 'Installiere die verpackte dsh-font 1.1.0-Fixture, löse das wirklich fehlende Client-Modul aus und verifiziere die automatische Quarantäne, gefolgt von einer nutzbaren Haupt-UI.',
  'lab.scenario.loaderPackageNameMismatch.title': 'Scoped Plugin Namensübereinstimmung des Loaders',
  'lab.scenario.loaderPackageNameMismatch.body': 'Installieren Sie eine sichere offline Scoped Fixture, deren Bundle Patch absichtlich ein fehlendes, unscoped Modul lädt, und überprüfen Sie dann die sofortige Attribution und Quarantäne nach der Installation.',
  'lab.scenario.startupTimeout.title': 'Startbetriebs-Timeout und Rollback',
  'lab.scenario.startupTimeout.body': 'Simuliere einen zeitgesteuerten Startbefehl und verifiziere Prozessabbruch, Rollback-Nachweis und fortgesetzten Start. Dieses Szenario ist standardmäßig nicht aktiviert.',
  'lab.scenario.transactionInterrupted.title': 'Wiederherstellung unterbrochener Plugin-Aktivierung',
  'lab.scenario.transactionInterrupted.body': 'Aktivieren Sie einen inerten Kandidaten in einem isolierten Zuhause und verwenden Sie dann eine frische CLI und deren Journal, um das vorherige Abhängigkeitsverzeichnis wiederherzustellen. Standardmäßig nicht aktiviert; das aktive Profil bleibt unverändert.',
  'lab.scenario.loaderDependency.title': 'Fehlende Aggregate-Plugin-Abhängigkeit',
  'lab.scenario.loaderDependency.body': 'Installiere ein Offline-Aggregate-Plugin, dessen Loader-Eintrag sich löst, dessen veröffentlichter Code aber absichtlich eine fehlende interne Host-Abhängigkeit anfordert, dann die sofortige Root-Attribution und Quarantäne überprüfen.',
  'lab.scenario.loaderExport.title': 'Plugin erwartet ein nicht verfügbares DSH-API',
  'lab.scenario.loaderExport.body': 'Installiere ein Offline-Plugin, das den eigentlichen Fehler reproduziert: Seine Abhängigkeit existiert, aber das Plugin erwartet eine API, die diese DSH-Generierung nicht exportiert. Setze das echte Harness wieder auf und überprüfe die Attribution und Quarantäne vor dem sicheren Modus-Fallback.',
  'lab.scenario.legacySessionApi.title': 'Plugin verwendet eine alte Session API',
  'lab.scenario.legacySessionApi.body': 'Installieren Sie ein inaktives Offline-Plugin, das das reproduzierte session.events-Muster trägt. Überprüfen Sie die genaue Zuordnung, ohne bei statischen Beweisen automatisch in Quarantäne zu stellen. Dieses Szenario ist standardmäßig nicht aktiviert.',
  'lab.scenario.immutableAgentInput.title': 'Plugin verändert eingefrorene Unterhaltungseingaben',
  'lab.scenario.immutableAgentInput.body': 'Installiert ein Offline-Diagnose-Plugin, das einen eingefrorenen Textblock in agent/pre-step direkt verändert und alle Unterhaltungen fehlschlagen lässt. Prüft Zuordnung und Hinweise zum Deaktivieren oder Deinstallieren ohne automatische Isolierung allein aufgrund statischer Hinweise.',
  'lab.scenario.settingsInvalid.title': 'Ungültig settings.yaml',
  'lab.scenario.settingsInvalid.body': 'Schreiben Sie doppelte Einstellungsschlüssel und verifizieren Sie, dass das normale Profil den Konfigurationsfehler meldet, der abgesicherte Modus ein isoliertes leeres Dokument verwendet und die Originaldatei unverändert bleibt.',
  'lab.scenario.module.title': 'Fehlendes Modulverzeichnis',
  'lab.scenario.module.body': 'Überprüfen Sie, ob der Fehler bei der Modulauflösung dem Besitz-Plugin zugeschrieben wird.',
  'lab.scenario.patch.title': 'Ungültiger Profil-Patch',
  'lab.scenario.patch.body': 'Finden Sie fehlerhafte cordis.patch.yml-Syntax in einer Testkopie.',
  'lab.scenario.duplicate.title': 'Doppelte Loader-Eintragung',
  'lab.scenario.duplicate.body': 'Reproduziert ein externes Plugin mit demselben Loader-Eintrag wie eine integrierte Client-Funktion und prüft Zuordnung, Quarantäne und sichere Bereinigung vor dem Start.',
  'lab.scenario.lifecycle.title': 'Fehler im Lebenszyklus des Loaders',
  'lab.scenario.lifecycle.body': 'Überprüfen Sie Fehlermontage, Rollback und Zuordnung zum Root-Plugin.',
  'lab.scenario.build.title': 'Blockiertes Build-Skript',
  'lab.scenario.build.body': 'Verwenden Sie ein gebündeltes ungefährliches Skript, um die genaue Genehmigung von allowBuilds zu überprüfen.',
  'lab.scenario.interrupted.title': 'Unterbrochene Wiederherstellung nach Reparatur',
  'lab.scenario.interrupted.body': 'Überprüfen Sie, dass ein späterer Durchlauf das Wiederherstellungstagebuch liest und die Szene bereinigt.',
