  'diagnostics.diagnosticMode.title': 'Das normale Profil konnte nicht starten; der Diagnosemodus ist bereit',
  'diagnostics.diagnosticMode.description': 'Dieser Prozess stellt nur Reparaturwerkzeuge bereit und bedeutet nicht, dass die App erfolgreich gestartet wurde. Beheben Sie das Problem und starten Sie anschließend das normale Profil neu.',
  'diagnostics.startup.title': 'Verlauf der Desktop-Startverschlechterung',
  'diagnostics.startup.description': 'Diese Schritte haben ein Zeitlimit überschritten oder wurden zurückgesetzt, ohne dass der Client ewig warten musste. Normale Zeitlimits zählen nicht als quarantänisierte Plugins.',
  'diagnostics.startup.issue': 'Eine Startoperation hat sich nicht rechtzeitig abgeschlossen',
  'diagnostics.startup.openLog': 'Harness-Protokoll öffnen',
  'diagnostics.startup.solution.profileCheck': 'Starten Sie neu, um die beschränkte schreibgeschützte Prüfung erneut durchzuführen, oder überprüfen Sie das Protokoll auf Eingriffe durch Festplatte und Sicherheitssoftware.',
  'diagnostics.startup.solution.profileRepair': 'Vom wiederhergestellten Sicherheitspunkt neu starten und erneut prüfen. Verwenden Sie einen Plugin-Snapshot, wenn die Reparatur weiterhin fehlschlägt.',
  'diagnostics.startup.solution.bundledPlugin': 'Nur dieses voreingestellte Plugin erneut versuchen. Sein Fehlschlag blockiert andere Plugins oder die Hauptoberfläche nicht.',
  'diagnostics.startup.solution.lockBusy': 'Schließen Sie die andere DSH-Instanz, die dieses Datenverzeichnis ändert. Bei einem beschädigten Lock prüfen Sie seinen Pfad im Protokoll.',
  'diagnostics.startup.solution.rollback': 'Das aktive Profil kann inkonsistent sein. Stellen Sie den neuesten bootfähigen Plugin-Snapshot wieder her oder wechseln Sie die Datenverzeichnisse.',
  'diagnostics.startup.legacyWorktree': 'Altes Worktree-Plugin muss manuell migriert werden',
  'diagnostics.startup.solution.legacyWorktreeBackupFailed': 'Die Worktree-Sicherung ist fehlgeschlagen; die ursprüngliche Konfiguration ist unverändert. Sichern Sie die betroffene package.json manuell, bevor Sie das alte Bundle entfernen. Das neue Experiment muss ausdrücklich aktiviert werden. Details stehen im Protokoll.',
  'diagnostics.startup.solution.legacyWorktree': 'Die alte Konfiguration wurde gesichert. Nichts wurde automatisch entfernt oder aktiviert. Den Sicherungspfad finden Sie im Protokoll. Entfernen Sie @deepseek-ai/dsh-experimental-tool-worktree manuell aus dsh.profile.bundles in der betroffenen package.json. Aktivieren Sie danach bei Bedarf das Experiment für Änderungsanfragen und Worktrees.',
  'diagnostics.startup.solution.unknown': 'Überprüfen Sie das Harness-Protokoll auf die verschlechterte Startoperation.',
  'diagnostics.startup.retry': 'Vorgang erneut versuchen',
  'diagnostics.startup.retrying': 'Wiederholung…',
  'diagnostics.startup.retryStarted': 'Neuinstallation gestartet',
  'diagnostics.startup.retryUnsupported': 'Dieser Vorfall kann nicht direkt erneut versucht werden. Befolgen Sie die empfohlenen Wiederherstellungsschritte.',
  'diagnostics.startup.snapshots': 'Plugin-Snapshots anzeigen',
  'diagnostics.issue.buildScript': 'Ein Plugin-Build-Skript benötigt Genehmigung',
  'diagnostics.issue.supplyChain': 'Eine Lieferkettenrichtlinie hat eine Abhängigkeit blockiert',
  'diagnostics.issue.network': 'Das Paket-Registry konnte nicht erreicht werden',
  'diagnostics.issue.packageManager': 'pnpm konnte den Profilvorgang nicht abschließen',
  'diagnostics.issue.loader': 'Cordis Loader konnte ein Plugin nicht laden',
  'diagnostics.issue.config': 'Eine Profilkonfigurationsdatei konnte nicht analysiert werden',
  'diagnostics.issue.runtime': 'Die gebündelte Desktop-Laufzeit konnte nicht gestartet werden',
  'diagnostics.issue.sessionApi': 'Ein Plugin könnte die entfernten Session.events API verwenden und verhindern, dass Konversationen geöffnet werden. Prüfen Sie auf ein kompatibles Update; falls betroffen, deaktivieren oder deinstallieren Sie es in der Plugin-Verwaltung. Statische Prüfungen sind beratend und stellen Plugins niemals automatisch unter Quarantäne oder ändern Konversationsdaten.',
  'diagnostics.issue.immutableAgentInput': 'Ein Plugin verändert möglicherweise in agent/pre-step die von Harness eingefrorene Unterhaltungseingabe. Dadurch kann jede Runde vor der Modellanfrage fehlschlagen. Aktualisieren, deaktivieren oder deinstallieren Sie das zugeordnete Plugin.',
  'diagnostics.issue.sessionPersistenceMigration': 'Dieses Profil wählt noch das entfernte SQLite-Session-Persistence-Backend. Öffnen Sie cordis.patch.yml und ersetzen Sie diesen Eintrag durch die aktuelle JSONL-Session-Persistence-Konfiguration. Bestehende SQLite-Daten werden nicht stillschweigend gelöscht oder konvertiert.',
