  'health.update.confirm.description': 'Der Client entfernt dauerhaft das inaktive alte Paket und dessen Quarantäne-Eintrag und öffnet dann den Markt mit demselben Paket. Die Ersatzversion muss weiterhin die bestehenden Lieferkettenprüfungen bestehen; das Mindestalter der Veröffentlichung wird nicht aufgehoben.',
