  'health.approveBuild.description': 'pnpm hat diese Abhängigkeit daran gehindert, ein lokales Build-Skript auszuführen. Die Bestätigung erlaubt nur den unten angegebenen genauen Abhängigkeitsschlüssel und versucht dieses isolierte Plugin erneut. Fahren Sie nur fort, nachdem Sie die Quelle überprüft und vertraut haben.',
