  'diagnostics.what.title': 'Что это проверяет',
  'diagnostics.what.body': 'Начиная с плагинов прямого профиля, доктор отслеживает зависимости и опциональные зависимости, сравнивает физические пути идентификационно-важных пакетов Host, таких как Cordis и runtime инструментов, и находит записи Loader, которые менеджер пакетов больше не может удалить. Действительные peerDependencies не сообщаются.',
  'diagnostics.safety.title': 'Что исправляет',
  'diagnostics.safety.body': 'Совместимые зависимости сначала сводятся к клиентской версии Host из пакета. Плагин, который нельзя безопасно свести, удаляется из активного профиля и сохраняется как запись в карантине. Только «Проверить и исправить» изменяет профиль; «Запустить проверку» всегда является только для чтения.',
