  'health.update.confirm.title': 'Удалить старую версию и найти совместимое обновление?',
  'health.update.confirm.description': 'Клиент окончательно удалит неактивный старый пакет и его запись в карантине, затем откроет рынок на том же пакете. Замена всё ещё должна проходить текущие проверки цепочки поставок; минимальный возраст релиза не изменяется.',
