  'lab.confirm.title': 'Executar o Perfil atual?',
  'lab.confirm.description': 'O Harness irá pausar e instalar plugins de diagnóstico reais no Perfil atual. Resultados de reparo e quarentena permanecem até Restaurar tudo; não modifique este Perfil a partir de outro processo do DSH enquanto isso.',
  'lab.confirm.acknowledge': 'Entendo que este exercício altera persistentemente o Perfil atual e confirmo que nenhuma outra instalação de DSH ou plugin está em execução',
