  'lab.confirm.start': 'Confirmar e iniciar',
  'lab.scenario.hostCompatible.title': 'Cópia sombra do Host compatível',
  'lab.scenario.hostCompatible.body': 'Verificar se uma segunda identidade Cordis pode convergir para o runtime empacotado com segurança.',
  'lab.scenario.hostIncompatible.title': 'Dependência do Host incompatível',
  'lab.scenario.hostIncompatible.body': 'Rastrear uma aresta dsh-tools incompatível até seu plugin raiz e colocá-la em quarentena.',
  'lab.scenario.orphan.title': 'Pacote órfão',
  'lab.scenario.orphan.body': 'Encontrar uma entrada fantasma do Loader cujo pacote de plugin desapareceu.',
  'lab.scenario.quarantineRemoval.title': 'Resíduo da remoção da quarentena',
  'lab.scenario.quarantineRemoval.body': 'Escrever o relatório de reparo, relatório de diagnóstico e referências do arquivo de bloqueio deixadas por uma desinstalação legada, e então verificar a detecção limitada e a limpeza.',
  'lab.scenario.clientModule.title': 'Compatibilidade do cliente dsh-font',
  'lab.scenario.clientModule.body': 'Instalar o fixture dsh-font 1.1.0 empacotado, acionar seu módulo de cliente real ausente e verificar a quarentena automática seguida por uma interface principal utilizável.',
  'lab.scenario.loaderPackageNameMismatch.title': 'Incompatibilidade no nome do Loader de plugin com escopo',
  'lab.scenario.loaderPackageNameMismatch.body': 'Instalar um fixture offline seguro com escopo, cujo Patch do Bundle carrega deliberadamente um módulo não escopo ausente, e então verificar a atribuição imediata e quarentena após a instalação.',
  'lab.scenario.startupTimeout.title': 'Tempo limite de operação de inicialização e reversão',
  'lab.scenario.startupTimeout.body': 'Simular um comando de inicialização com tempo esgotado e verificar cancelamento do processo, evidência de reversão e continuidade da inicialização. Este cenário não é verificado por padrão.',
  'lab.scenario.transactionInterrupted.title': 'Recuperação de ativação de plugin interrompida',
  'lab.scenario.transactionInterrupted.body': 'Ativar um candidato inerte em um ambiente isolado, depois usar um CLI fresco e seu diário para restaurar o diretório de dependências anterior. Não verificado por padrão; o Perfil ativo permanece inalterado.',
  'lab.scenario.loaderDependency.title': 'Dependência de plugin agregado ausente',
  'lab.scenario.loaderDependency.body': 'Instalar um plugin agregado offline cuja entrada do Loader resolve, mas cujo código publicado solicita deliberadamente uma dependência interna do Host ausente, e então verificar a atribuição raiz imediata e quarentena.',
  'lab.scenario.loaderExport.title': 'Plugin espera um DSH API indisponível',
  'lab.scenario.loaderExport.body': 'Instalar um plugin offline que reproduz a falha real: sua dependência existe, mas o plugin espera uma API que esta geração de DSH não exporta. Retomar o Harness real e verificar atribuição e quarentena antes do modo de diagnóstico.',
  'lab.scenario.legacySessionApi.title': 'Plugin usa um API de Session legado',
  'lab.scenario.legacySessionApi.body': 'Instale um plugin offline inerte que contenha o padrão session.events reproduzido. Verifique a atribuição precisa sem colocar automaticamente em quarentena com base em evidências estáticas. Este cenário está desmarcado por padrão.',
  'lab.scenario.immutableAgentInput.title': 'Plugin altera entrada de conversa congelada',
  'lab.scenario.immutableAgentInput.body': 'Instala um plugin de diagnóstico offline que altera diretamente um bloco de texto congelado em agent/pre-step e faz todas as conversas falharem. Verifica a atribuição e a orientação para desativar ou desinstalar sem isolamento automático baseado apenas em evidência estática.',
  'lab.scenario.settingsInvalid.title': 'settings.yaml inválido',
  'lab.scenario.settingsInvalid.body': 'Escreva chaves de configuração duplicadas e verifique se o Perfil normal reporta o erro, o modo de diagnóstico usa um documento vazio isolado e o arquivo original permanece inalterado.',
  'lab.scenario.module.title': 'Diretório do módulo ausente',
  'lab.scenario.module.body': 'Verifique a atribuição de falha na resolução do módulo para o plugin proprietário.',
  'lab.scenario.patch.title': 'Patch de Perfil inválido',
  'lab.scenario.patch.body': 'Localize a sintaxe cordis.patch.yml malformada em uma cópia de teste.',
  'lab.scenario.duplicate.title': 'Entrada de Loader duplicada',
  'lab.scenario.duplicate.body': 'Reproduz um plugin externo com a mesma entrada de Loader de um recurso integrado e verifica atribuição, quarentena e limpeza segura antes da inicialização.',
  'lab.scenario.lifecycle.title': 'Falha no ciclo de vida do Loader',
  'lab.scenario.lifecycle.body': 'Verifique falha de montagem, reversão e atribuição ao plugin raiz.',
  'lab.scenario.build.title': 'Script de compilação bloqueado',
  'lab.scenario.build.body': 'Use um script inofensivo incluído para verificar aprovação exata do allowBuilds.',
  'lab.scenario.interrupted.title': 'Recuperação de reparo interrompida',
  'lab.scenario.interrupted.body': 'Verifique se uma execução posterior lê o diário de recuperação e limpa a cena.',
