  'diagnostics.startup.issue': 'Uma operação de inicialização não foi concluída a tempo',
  'diagnostics.startup.openLog': 'Abrir registro do Harness',
  'diagnostics.startup.solution.profileCheck': 'Reinicie para executar novamente a verificação limitada de leitura apenas, ou inspecione o registro quanto a interferência de disco e software de segurança.',
  'diagnostics.startup.solution.profileRepair': 'Reinicie a partir do ponto seguro restaurado e verifique novamente. Use uma captura de plugin se o reparo ainda falhar.',
  'diagnostics.startup.solution.bundledPlugin': 'Tente apenas este plugin predefinido novamente. Sua falha não bloqueará outros plugins ou a interface principal.',
