  'diagnostics.startup.solution.rollback': 'O Perfil ativo pode estar inconsistente. Restaure a última captura de plugin inicializável ou altere os diretórios de dados.',
  'diagnostics.startup.legacyWorktree': 'O plugin antigo de worktree precisa de migração manual',
  'diagnostics.startup.solution.legacyWorktreeBackupFailed': 'A cópia de segurança do worktree falhou; o original não mudou. Guarde manualmente o package.json afetado antes de remover o bundle antigo. A nova experiência exige ativação explícita. Consulte o registo.',
  'diagnostics.startup.solution.legacyWorktree': 'A configuração antiga foi guardada numa cópia de segurança. Nada foi removido ou ativado automaticamente. Consulte a cópia no registo e remova manualmente @deepseek-ai/dsh-experimental-tool-worktree de dsh.profile.bundles no package.json afetado. Depois ative a experiência de pedidos de alteração e worktrees se desejar.',
