  'diagnostics.issue.immutableAgentInput': 'Um plugin pode alterar em agent/pre-step uma entrada de conversa congelada pelo Harness, fazendo cada turno falhar antes da solicitação ao modelo. Atualize, desative ou desinstale o plugin atribuído.',
  'diagnostics.issue.sessionPersistenceMigration': 'Este Perfil ainda seleciona o backend de persistência de sessão SQLite removido. Abra cordis.patch.yml e substitua essa entrada pela configuração atual de persistência de sessão JSONL. Dados SQLite existentes não são excluídos ou convertidos silenciosamente.',
