  'diagnostics.uninstall.confirm.title': 'Desinstalar o plugin afetado?',
  'diagnostics.uninstall.confirm.description': 'O gerenciador de plugins padrão do dsh removerá este plugin e sua configuração de pacote do perfil Web atual. Isso não modifica o mercado de plugins.',
  'diagnostics.uninstall.confirm.acknowledge': 'Eu confirmo que quero desinstalar este plugin do perfil Web atual',
  'diagnostics.uninstall.confirm.cancel': 'Cancelar',
  'diagnostics.uninstall.confirm.action': 'Desinstalar',
  'diagnostics.what.title': 'O que isso verifica',
  'diagnostics.what.body': 'Começando a partir de plugins de perfil direto, o médico segue dependências e optionalDependencies, compara os caminhos físicos de pacotes Host sensíveis à identidade, como Cordis e o runtime da ferramenta, e encontra entradas de Loader que o gerenciador de pacotes não pode mais remover. peerDependencies válidas não são relatadas.',
  'diagnostics.safety.title': 'Quais alterações de reparo',
  'diagnostics.safety.body': 'Dependências compatíveis são convergidas primeiro para a cópia do Host incluída no cliente. Um plugin que não pode ser convergido com segurança é removido do perfil ativo e mantido como registro de quarentena. Apenas “Verificar e reparar” modifica o perfil; “Executar verificação” é sempre apenas leitura.',
  'viewInPreset': 'Ver no grupo de predefinições',
  'health.repaired': 'Ação anterior: As dependências principais do Harness foram convergidas automaticamente e o plugin permanece habilitado.',
  'health.quarantined': 'Ação anterior: um conflito de dependência de plugin inseguro foi detectado e o plugin afetado foi colocado em quarentena.',
  'health.failed': 'Ação anterior: o conflito de dependência do plugin não pôde ser reparado, então o Harness bloqueou o perfil danificado.',
  'health.dismiss': 'Ignorar',
  'quarantineNotice.title': 'Plugin incompatível em quarentena',
  'quarantineNotice.description': 'O cliente não pôde carregar este plugin com segurança, então ele foi removido do perfil ativo antes que pudesse afetar outras funcionalidades.',
  'quarantineNotice.count': '{count} plugin(ns) foram detectados e colocados em quarentena',
