  'quarantineNotice.dismiss': 'Ignorar',
  'quarantineNotice.openDiagnostics': 'Abrir Diagnósticos',
  'quarantineNotice.dismissFailed': 'O reconhecimento não pôde ser salvo. A quarentena continua ativa.',
  'health.quarantine.title': 'Plugins em quarentena',
  'health.quarantine.description': 'Esses plugins foram removidos do perfil ativo enquanto suas versões e registros de conflito foram mantidos.',
  'health.quarantine.reason.hostVersionIncompatible': 'Plugin exclui esta versão do Harness',
  'health.quarantine.reason.incompatible': 'Dependência de Host incompatível',
  'health.quarantine.reason.convergenceFailed': 'Convergência de dependência falhou',
  'health.quarantine.reason.orphanedBundle': 'Entrada de Loader órfã',
  'health.quarantine.reason.buildScriptBlocked': 'Script de build bloqueado pela política',
  'health.quarantine.reason.clientModuleUnavailable': 'Módulo do cliente indisponível',
  'health.quarantine.reason.loaderModuleUnresolvable': 'Nome de módulo de Loader de plugin inválido',
  'health.quarantine.reason.loaderDependencyUnavailable': 'Dependência do plugin ou API incompatível',
  'health.quarantine.reason.loaderLifecycleFailed': 'Falha no ciclo de vida de inicialização do plugin',
  'health.quarantine.reason.loaderEntryCollision': 'O plugin duplica um recurso integrado',
  'health.quarantine.conflict.requires': 'O plugin declara',
  'health.quarantine.conflict.hostUses': 'Host incluído',
  'health.quarantine.conflict.incompatible': 'os intervalos são incompatíveis, então o plugin não pode compartilhar o runtime de forma segura e foi removido do Perfil ativo',
  'health.quarantine.conflict.convergence': 'os intervalos são compatíveis, mas a convergência de dependência falhou, então o plugin foi removido do Perfil ativo',
  'health.quarantine.analysis.incompatible-host-version': 'O próprio manifesto de compatibilidade do plugin exclui explicitamente esta versão do Harness. O cliente bloqueou a ativação antes de executar o código do plugin para que uma versão conhecida como incompatível não derrube outros plugins.',
  'health.quarantine.analysis.incompatible-host-dependency': 'O plugin possui uma dependência de Host sensível à identidade que é incompatível com a versão incluída, então ambas as cópias não podem coexistir com segurança em um único processo.',
  'health.quarantine.analysis.convergence-failed': 'Os intervalos de dependência parecem compatíveis, mas o gerenciador de pacotes não pôde convergir o plugin para a instância de Host incluída.',
  'health.quarantine.analysis.orphaned-bundle': 'O plugin permanece na lista do Loader, mesmo que o manifesto de dependência do Perfil não possa mais gerenciá-lo ou desinstalá-lo.',
  'health.quarantine.analysis.build-script-blocked': 'O pnpm bloqueou um script de build de dependência. O cliente desativou o plugin para que a interface principal ainda possa iniciar; aprove e tente novamente apenas após verificar a origem.',
  'health.quarantine.analysis.client-module-unavailable': 'O cliente do plugin solicitou um módulo que esta build não pode fornecer. O cliente desativou o plugin para que o restante da aplicação possa iniciar; tente novamente após atualizar o plugin ou o cliente.',
  'health.quarantine.analysis.loader-module-unresolvable': 'O pacote raiz do plugin está instalado, mas seu Patch de Bundle referencia um módulo de Loader que não pode ser resolvido. O cliente desativou imediatamente o plugin para que esta versão com problemas não bloqueie a próxima inicialização.',
  'health.quarantine.analysis.loader-dependency-unavailable': 'O módulo do Loader é resolvido, mas seu código publicado importa uma dependência interna que o Perfil ativo não pode fornecer ou espera uma exportação API ausente desta geração DSH. O cliente atribui a falha ao plugin externo e o coloca em quarentena para que um plugin incompatível não derrube toda a interface.',
  'health.quarantine.analysis.loader-lifecycle-failed': 'O módulo do plugin foi carregado, mas apresentou erro ao iniciar ou registrar serviços. O cliente identificou o plugin responsável a partir da entrada do Loader e da fonte do Bundle, então o colocou em quarentena para que os plugins e configurações restantes possam continuar a iniciar.',
  'health.quarantine.analysis.loader-entry-collision': 'O plugin registra uma entrada de Loader que já pertence a um recurso integrado deste cliente. O cliente mantém a implementação integrada e coloca o plugin em quarentena para impedir que a entrada duplicada bloqueie toda a inicialização.',
  'health.quarantine.solution.title': 'Resolução recomendada',
  'health.quarantine.solution.incompatible-host-version': 'Remova a versão em quarentena e encontre uma atualização que suporte esta versão do Harness no mercado. Não continue restaurando a mesma versão; ela permanecerá inativa até que seu manifesto de compatibilidade inclua este Host.',
  'health.quarantine.solution.incompatible-host-dependency': 'Procure primeiro uma versão de plugin compatível com esta versão do DSH, depois restaure-a após o plugin ou cliente de desktop ser atualizado. Remova-a permanentemente quando não houver uma versão compatível disponível.',
  'health.quarantine.solution.convergence-failed': 'Use “Relink and restore” para que o pnpm possa integrar o plugin à dependência Host incluída. Uma tentativa falha reverte a ação e deixa o plugin em quarentena.',
  'health.quarantine.solution.orphaned-bundle': 'Reinstale o plugin a partir de sua fonte original se você ainda precisar dele, ou remova-o permanentemente para limpar a entrada do Loader obsoleta.',
  'health.quarantine.solution.build-script-blocked': 'Verifique a fonte do plugin e o pacote de build solicitado, então aprove apenas a chave de build exatamente mostrada. Mantenha-o em quarentena ou remova-o se a fonte não for confiável.',
  'health.quarantine.solution.client-module-unavailable': 'Esta versão do plugin é destinada a uma geração de cliente incompatível, então restaurar a mesma versão falhará novamente. Remova a versão antiga em quarentena e instale uma atualização compatível do mercado. Se o mercado ainda resolver a versão antiga, aguarde que a nova versão atinja a idade mínima da cadeia de fornecimento.',
  'health.quarantine.solution.loader-module-unresolvable': 'O pacote do plugin contém um nome de módulo Loader incorreto ou arquivos publicados incompletos, então restaurar a mesma versão falhará novamente. Remova a versão antiga em quarentena e encontre uma versão corrigida no mercado; entre em contato com o autor do plugin para corrigir o Bundle Patch quando não houver atualização.',
  'health.quarantine.solution.loader-dependency-unavailable': 'Instale uma versão de plugin compatível com esta versão do DSH. Se a falha mencionar um pacote Host @deepseek-ai/dsh-* ou uma exportação API removida, não instale outra versão do Host no Perfil: o plugin é destinado a outra geração do DSH e seu autor deve migrar o API e publicar um build compatível.',
  'health.quarantine.solution.loader-lifecycle-failed': 'Verifique primeiro no mercado de plugins se há uma atualização compatível. Restaurar a mesma versão pode repetir a falha de inicialização; quando não houver atualização, desinstale completamente a versão em quarentena e compartilhe o relatório de diagnóstico com o autor do plugin.',
  'health.quarantine.solution.loader-entry-collision': 'Esta versão do plugin entra em conflito com um recurso integrado. Remova completamente a versão antiga e reinstale somente quando houver uma versão compatível que não registre mais a entrada duplicada.',
  'health.quarantine.action.compatibleRetry': 'Encontre a versão compatível e tente novamente',
  'health.quarantine.action.convergeRetry': 'Relink e restaurar',
  'health.quarantine.action.restoreSource': 'Reinstalar da fonte original',
  'health.quarantine.action.findUpdate': 'Remover versão antiga e encontrar atualização',
