  'health.quarantine.originalSpec': 'Fonte original:',
  'health.update.confirm.title': 'Remover a versão antiga e encontrar atualização compatível?',
  'health.update.confirm.description': 'O cliente removerá permanentemente o pacote antigo inativo e seu registro de quarentena, então abrirá o mercado no mesmo pacote. A substituição ainda deve passar nas verificações existentes da cadeia de fornecimento; a idade mínima do lançamento não é flexibilizada.',
  'health.update.confirm.acknowledge': 'Confirmo que a versão antiga em quarentena pode ser removida e verei a versão de substituição',
  'health.update.confirm.action': 'Remover e abrir mercado',
  'health.retry': 'Tentar reparo novamente',
