  'diagnostics.startup.solution.legacyWorktreeBackupFailed': '이전 worktree 백업에 실패했으며 원본 설정은 변경되지 않았습니다. 해당 package.json을 수동으로 백업한 후 이전 bundle을 제거하세요. 새 실험 기능은 직접 활성화해야 합니다. 자세한 오류는 로그를 확인하세요.',
  'diagnostics.startup.solution.legacyWorktree': '이전 설정은 백업되었습니다. 자동 삭제나 새 기능 활성화는 하지 않았습니다. 로그에서 백업 위치를 확인하고 해당 package.json의 dsh.profile.bundles에서 @deepseek-ai/dsh-experimental-tool-worktree를 직접 제거하세요. 필요한 경우 변경 요청 및 worktree 실험 기능을 활성화하세요.',
